mapper.select:
SELECT d.dispatch_id AS snapshot_id, d.dispatch_id, d.op_seq, d.process_name, COALESCE(rpt.stat_date, DATE(d.actual_start)) AS snapshot_date, d.resource_id, d.resource_name, d.work_order_id, d.work_order_no, ROUND(CASE WHEN d.plan_start IS NOT NULL AND d.plan_end IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, d.plan_start, d.plan_end) / 60.0 ELSE 0 END, 2) AS planned_hours, ROUND(CASE WHEN d.actual_start IS NOT NULL AND d.actual_end IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, d.actual_start, d.actual_end) / 60.0 ELSE 0 END, 2) AS run_hours, COALESCE(dt.dt_hours, 0) AS downtime_hours, CASE WHEN d.actual_end IS NOT NULL AND d.plan_start IS NOT NULL AND d.plan_end IS NOT NULL AND TIMESTAMPDIFF(MINUTE, d.plan_start, d.plan_end) > 0 THEN ROUND( (CASE WHEN d.actual_start IS NOT NULL AND d.actual_end IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, d.actual_start, d.actual_end) ELSE 0 END - COALESCE(dt.dt_minutes, 0)) / TIMESTAMPDIFF(MINUTE, d.plan_start, d.plan_end), 4) ELSE 0 END AS availability, CASE WHEN d.plan_qty > 0 AND d.good_qty > 0 THEN ROUND(d.good_qty / d.plan_qty, 4) ELSE 0 END AS performance, CASE WHEN d.good_qty > 0 THEN ROUND(d.good_qty / (d.good_qty + d.defect_qty), 4) ELSE 0 END AS quality_rate, CASE WHEN d.actual_end IS NOT NULL AND d.plan_start IS NOT NULL AND d.plan_end IS NOT NULL AND TIMESTAMPDIFF(MINUTE, d.plan_start, d.plan_end) > 0 AND d.plan_qty > 0 AND d.good_qty > 0 THEN ROUND( ((CASE WHEN d.actual_start IS NOT NULL AND d.actual_end IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, d.actual_start, d.actual_end) ELSE 0 END - COALESCE(dt.dt_minutes, 0)) / TIMESTAMPDIFF(MINUTE, d.plan_start, d.plan_end)) * (d.good_qty / d.plan_qty) * (CASE WHEN (d.good_qty + d.defect_qty) > 0 THEN d.good_qty / (d.good_qty + d.defect_qty) ELSE 0 END) , 4) ELSE 0 END AS oee, d.plan_qty AS plan_qty, d.good_qty AS good_qty, d.defect_qty AS defect_qty, d.create_time FROM mms_dispatch d LEFT JOIN ( SELECT r.work_order_id, r.process_id, MAX(DATE(r.report_time)) AS stat_date FROM mms_work_report r WHERE r.del_flag = '0' GROUP BY r.work_order_id, r.process_id ) rpt ON rpt.work_order_id = d.work_order_id AND rpt.process_id = d.process_id LEFT JOIN ( SELECT dt.dispatch_id, SUM(dt.minutes) AS dt_minutes, ROUND(SUM(dt.minutes) / 60.0, 2) AS dt_hours FROM mms_downtime dt WHERE dt.del_flag = '0' GROUP BY dt.dispatch_id ) dt ON dt.dispatch_id = d.dispatch_id
d.del_flag = '0' AND d.actual_start IS NOT NULL AND d.resource_name LIKE CONCAT('%', #{resourceName}, '%') AND d.work_order_no LIKE CONCAT('%', #{workOrderNo}, '%') AND COALESCE(rpt.stat_date, DATE(d.actual_start)) >= #{params.beginTime} AND COALESCE(rpt.stat_date, DATE(d.actual_start)) <= #{params.endTime}
ORDER BY snapshot_date DESC, d.work_order_id DESC, d.op_seq ASC
